        }

        return IsRelative
            ? path.CombineWithFilePath(this).Collapse()
            : new FilePath(FullPath);
    }

    /// <summary>
    /// Collapses a <see cref="FilePath"/> containing ellipses.
    /// </summary>
    /// <returns>A collapsed <see cref="FilePath"/>.</returns>
    public FilePath Collapse()
    {
